 rows=[a for a in actions if a['profile'].startswith(f'professions-class-{cid}-ally-')];primary=next(a for a in rows if a['key']==('walk-up'if cid==9 else f'original_class_{cid}_normal'));v=primary.get('closeVideo')or primary['video'];poster=v.replace('/videos/','/stills/').replace('.mp4','.png');links=''.join('<li><a href="../index.html?action='+quote(a['id'])+'">'+e(profiles[a['profile']]['contextName']+' · '+a['name'])+'</a><a class="download" href="../'+e(a['video'])+'">视频</a></li>'for a in rows)
 blocks.append('<article><div class="tag">sol · '+str(len(rows))+' 条完整演示</div><h2>'+name+'</h2><p>'+summary+'</p><video controls muted playsinline preload="none" poster="../'+e(poster)+'" src="../'+e(v)+'"></video><nav><a href="../index.html?action='+quote(primary['id'])+'">进入逐帧对照</a><a href="../professions/class-'+str(cid)+'-ally/qa-report.json">本组QA与差异</a></nav><details><summary>全部动作与视频（'+str(len(rows))+'）</summary><ul>'+links+'</ul></details></article>')
